def solve(grid):
    """
    Transforms the input grid according to the discovered rule.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # ------------------------------------------------------------
    # 1. Find all connected components of 2's (clusters)
    # ------------------------------------------------------------
    visited = [[False] * cols for _ in range(rows)]
    clusters = []                     # each element is a dict with keys:
                                     # 'cells', 'rows', 'cols',
                                     # 'min_row','max_row','min_col','max_col'

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2 and not visited[r][c]]:
                # BFS to collect the whole component
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols \
                                and grid[nr][nc] == 2 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr, nc))
                row_set = {cr for cr, _ in cells}
                col_set = {cc for _, cc in cells}
                clusters.append({
                    'cells': cells,
                    'rows': row_set,
                    'cols': col_set,
                    'min_row': min(row_set),
                    'max_row': max(row_set),
                    'min_col': min(col_set),
                    'max_col': max(col_set)
                })

    # ------------------------------------------------------------
    # 2. Helper structures: for each row/column, which clusters appear
    # ------------------------------------------------------------
    row_to_clusters = [set() for _ in range(rows)]
    col_to_clusters = [set() for _ in range(cols)]

    for idx, cl in enumerate(clusters):
        for r in cl['rows']:
            row_to_clusters[r].add(idx)
        for c in cl['cols']:
            col_to_clusters[c].add(idx)

    # ------------------------------------------------------------
    # 3. Row bridging: connect clusters that share a row
    # ------------------------------------------------------------
    for r in range(rows):
        cluster_set = row_to_clusters[r]
        if len(cluster_set) >= 2:
            min_c = min(clusters[i]['min_col'] for i in cluster_set)
            max_c = max(clusters[i]['max_col'] for i in cluster_set)
            for c in range(min_c + 1, max_c):
                if grid[r][c] == 0:
                    grid[r][c] = 1

    # ------------------------------------------------------------
    # 4. Column bridging: connect clusters that share a column
    # ------------------------------------------------------------
    for c in range(cols):
        cluster_set = col_to_clusters[c]
        if len(cluster_set) >= 2:
            min_r = min(clusters[i]['min_row'] for i in cluster_set)
            max_r = max(clusters[i]['max_row'] for i in cluster_set)
            if max_r - min_r > 1:
                # vertical interior
                for rr in range(min_r + 1, max_r):
                    if grid[rr][c] == 0:
                        grid[rr][c] = 1
                # horizontal bar at the first intermediate row
                r_bar = min_r + 1
                for dc in (-1, 0, 1):
                    nc = c + dc
                    if 0 <= nc < cols and grid[r_bar][nc] == 0:
                        grid[r_bar][nc] = 1

    # ------------------------------------------------------------
    # 5. Determine isolation flags for each cluster
    # ------------------------------------------------------------
    n = len(clusters)
    horiz_shared = [False] * n
    vert_shared = [False] * n

    for i in range(n):
        for j in range(i + 1, n):
            if clusters[i]['rows'] & clusters[j]['rows']:
                horiz_shared[i] = horiz_shared[j] = True
            if clusters[i]['cols'] & clusters[j]['cols']:
                vert_shared[i] = vert_shared[j] = True

    # ------------------------------------------------------------
    # 6. Leftward extension for clusters isolated both horizontally
    #    and vertically
    # ------------------------------------------------------------
    for i in range(n):
        if not horiz_shared[i] and not vert_shared[i]:
            cl = clusters[i]
            for r in cl['rows']:
                for c in range(0, cl['min_col']):
                    if grid[r][c] == 0:
                        grid[r][c] = 1

    # ------------------------------------------------------------
    # 7. Vertical extension for clusters that are vertically isolated
    #    but belong to a horizontal group (the rightmost cluster in
    #    that group is extended downwards)
    # ------------------------------------------------------------
    for i in range(n):
        if not vert_shared[i] and horiz_shared[i]:
            cl_i = clusters[i]
            # find the whole horizontal group (clusters sharing any row)
            group = set()
            for j in range(n):
                if cl_i['rows'] & clusters[j]['rows']:
                    group.add(j)

            # identify the rightmost cluster of the group
            rightmost_idx = max(group, key=lambda j: clusters[j]['max_col'])
            if rightmost_idx != i:
                continue   # only the rightmost cluster is extended

            # ----- perform the vertical extension -----
            r_max = cl_i['max_row']

            # find the leftmost cluster of the group to know the interior range
            leftmost_idx = min(group, key=lambda j: clusters[j]['min_col'])
            interior_min = clusters[leftmost_idx]['max_col'] + 1

            # immediate two rows: columns directly left of the cluster
            for r in (r_max + 1, r_max + 2):
                if r >= rows:
                    break
                for d in (-1, -2):
                    c = cl_i['min_col'] + d
                    if 0 <= c < cols and grid[r][c] == 0:
                        grid[r][c] = 1

            # remaining rows: fill the whole interior plus the cluster itself
            for r in range(r_max + 3, rows):
                for c in range(interior_min, cl_i['max_col'] + 1):
                    if grid[r][c] == 0:
                        grid[r][c] = 1

    return grid

